import z3

N = 54
max_v = 27
s = z3.Solver()

placements = {}
for v in range(1, max_v + 1):
    d = v + 1
    num_pos = N - d
    placements[v] = [z3.Bool(f'p_{v}_{k}') for k in range(num_pos)]

for v in range(1, max_v + 1):
    s.add(z3.Sum([z3.If(b, 1, 0) for b in placements[v]]) == 1)

for i in range(N):
    claims = []
    for v in range(1, max_v + 1):
        d = v + 1
        if i < (N - d):
            claims.append(placements[v][i])
        start_end = i - d
        if start_end >= 0 and start_end < (N - d):
            claims.append(placements[v][start_end])
    s.add(z3.Sum([z3.If(b, 1, 0) for b in claims]) == 1)

print(s.check())
if s.check() == z3.sat:
    m = s.model()
    seq = [0] * N
    for v in range(1, max_v + 1):
        for k in range(len(placements[v])):
            if m.evaluate(placements[v][k]):
                d = v + 1
                seq[k] = v
                seq[k + d] = v
                break
    print(seq)
else:
    print("UNSAT")
